# owner: platform
"""Plain-text absence notices for parents."""

from rosterkit.models import Student

ABSENT = "absent"


def absent_days(student: Student, marks: list) -> list:
    """Sorted absent dates, or error on foreign marks."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError("mark for a different student")
    gone = [item for item in marks if item.status == ABSENT]
    return sorted(item.day for item in gone)


def build_notice(student: Student, marks: list) -> str:
    """Short notice with the student and days missed."""
    days = absent_days(student, marks)
    if not days:
        raise ValueError("no absences to report")
    dates = ", ".join(day.isoformat() for day in days)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {len(days)} day(s): {dates}."

