# owner: platform
import unittest

from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("7", "Rivera", "Ana", "A")


def mark(day, status="absent", who="7"):
    return Mark(who, date(2026, 3, day), status)


class NoticeTests(unittest.TestCase):
    def test_lists_absent_days_in_order(self):
        marks = [mark(9), mark(4, "present"), mark(2)]
        text = build_notice(PUPIL, marks)
        self.assertEqual(
            text,
            "Ana Rivera missed 2 day(s): "
            "2026-03-02, 2026-03-09."
        )

    def test_other_student_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(2), mark(3, who="8")])

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(2, "late")])
